def evaluate(evidence: dict) -> bool:
    paths = [a.get('path','').replace('\\','/') for a in evidence.get('artifacts', []) if a.get('kind') == 'chart' or a.get('path','').lower().endswith(('.png','.svg','.html','.pdf'))]
    return bool(paths) and all(p.startswith('output/') for p in paths)
